    if($('aerisRelicStrip'))$('aerisRelicStrip').innerHTML=missions.map(m=>`<span class="aerisRelicChip ${state.relics.includes(m.id)?'':'locked'}" title="${relic(m)}">${state.relics.includes(m.id)?'◆':'◇'} ${relic(m)}</span>`).join('');
